 if(mode==='supplier')fields=['name','org','contact','email','phone','address','postal','city','bankgiro','plusgiro'].map(k=>pField(k,k,r[k],k==='email'?'email':'text',k==='name')).join('')+pField('terms','terms',r.terms,'number',true)+`<label class="hr-check"><input type="checkbox" name="active" ${r.active!==false?'checked':''}>${pt('active')}</label><label class="field wide"><span>${pt('notes')}</span><textarea name="notes" maxlength="2000">${esc(r.notes||'')}</textarea></label>`;
 if(mode==='order'||mode==='invoice'){
  const invoice=mode==='invoice';
  fields=`<div class="notice wide">${pt(invoice?'invoiceNotice':'orderNotice')+(invoice?'':' '+it('invOrderHelp'))}</div>`+pSelect('supplierId','supplier',r.supplierId,pSupplierOptions())+pField('date','date',r.date,'date',true)+(invoice?pField('due','due',r.due,'date',true)+pField('invoiceNo','invoiceNo',r.invoiceNo)+pField('reference','reference',r.reference)+pField('paymentReference','paymentReference',r.paymentReference)+pField('documentTotal','documentTotal',r.documentTotal,'number')+pField('rounding','rounding',r.rounding,'number')+pSelect('orderId','linkedOrder',r.orderId||'',[['','—'],...pData().orders.filter(o=>o.supplierId===r.supplierId&&['issued','closed'].includes(o.status)).map(o=>[o.id,'IO'+o.number])],false):pField('expected','expected',r.expected,'date')+pField('reference','reference',r.reference))+pLinesEditor(r,invoice)+`<label class="field wide"><span>${pt('note')}</span><textarea name="note" maxlength="2000">${esc(r.note||'')}</textarea></label>`;
 }
 if(mode==='receive'){
  const o=pData().orders.find(o=>o.id===r.id);
  fields=pField('date','date',r.date||today(),'date',true)+pField('reference','deliveryReference',r.reference,'text',true)+`<div class="wide">${o.lines.map(l=>`<label class="field purchase-receive-row"><span>${esc(l.description)} · ${pt('remainingQty')}: ${number(l.quantity-o.received[l.id])} ${esc(l.unit)}</span><input type="number" data-receipt-line="${l.id}" value="0" min="0" max="${number(l.quantity-o.received[l.id])}" step="0.01"></label>`).join('')}</div>`;
 }
 if(['cancelOrder','closeOrder','reverseReceipt','cancelInvoice'].includes(mode))fields=pField('reason','reason','','text',true);
 if(['post','payment','reversePayment'].includes(mode)){
  fields=pSelect('yearId','year',r.yearId,[['',pt('choose')],...state.accounting.years.filter(y=>!y.closed).map(y=>[y.id,y.name])]);
  if(mode==='post'){
   submit='postInvoice';fields=`<div class="notice wide">${pt('scope')}</div>`+fields+pField('date','postingDate',r.date,'date',true)+pField('description','descriptionPosting',r.description,'text',true)+pAccount('liabilityAccount','liabilityAccount',r.liabilityAccount,['liability'])+(r.needsVat===false?'':pAccount('vatAccount','vatAccount',r.vatAccount,['liability','asset']))+(r.rounding?pAccount('roundingAccount','roundingAccount',r.roundingAccount,['income','expense']):'')+`<h3 class="wide">${pt('total')}: ${money(r.total)}</h3><label class="hr-check wide"><input name="reviewed" type="checkbox" required>${pt('reviewed')}</label>`;
  }else if(mode==='payment'){
   submit='registerPayment';fields=`<div class="notice wide">${pt('paymentNotice')}</div>`+fields+pField('date','paymentDate',r.date,'date',true)+pField('postingDate','postingDate',r.postingDate,'date',true)+pField('amount','amount',r.amount,'number',true)+pAccount('bankAccount','bankAccount',r.bankAccount,['asset'])+pField('reference','bankReference',r.reference,'text',true)+pField('description','descriptionPosting',r.description,'text',true)+`<label class="hr-check wide"><input name="reviewed" type="checkbox" required>${pt(r.type==='credit'?'refundReviewed':'paymentReviewed')}</label>`;
  }else{fields=`<div class="notice wide">${pt('reverseNotice')}</div>`+fields+pField('date','reversalDate',r.date,'date',true)+pField('reason','reason',r.reason,'text',true);}
 }
 const root=document.querySelector('#modal-root');root.innerHTML=`<dialog class="editor large" aria-labelledby="purchase-editor-title"><form id="purchase-form"><div class="dialog-head"><h2 id="purchase-editor-title">${mode==='supplier'&&r.id?`${pt('supplier')} ${r.number}`:mode==='order'&&r.id?`${pt('orders')} IO${r.number}`:mode==='invoice'&&r.id?`${pt(r.type)} LF${r.number}`:pt(title)}</h2><button type="button" class="icon-button" id="purchase-close" aria-label="${t('close')}">×</button></div><div class="dialog-body form-grid">${fields}<p class="hr-error wide" id="purchase-error" role="alert"></p></div><div class="dialog-foot"><span></span><div><button type="button" class="secondary" id="purchase-cancel">${pt('cancel')}</button><button class="primary" type="submit">${pt(submit)}</button></div></div></form></dialog>`;
 const dialog=root.querySelector('dialog');dialog.showModal();const close=()=>{editor=null;dialog.close();root.innerHTML='';};document.querySelector('#purchase-close').onclick=close;document.querySelector('#purchase-cancel').onclick=close;dialog.oncancel=()=>{editor=null;};
 const form=document.querySelector('#purchase-form');
 if(mode==='supplier'){form.querySelector('[name=terms]').step='1';form.querySelector('[name=terms]').min='0';form.querySelector('[name=terms]').max='365';}
 if(mode==='post'&&r.type==='credit'){const orig=pData().invoices.find(i=>i.id===r.originalId);if(orig?.liabilityAccount){form.querySelector('[name=liabilityAccount]').value=orig.liabilityAccount;form.querySelector('[name=liabilityAccount]').disabled=true;r.liabilityAccount=orig.liabilityAccount;}}
 if(['order','invoice'].includes(mode)){
  form.querySelectorAll('[data-key=articleId]').forEach(select=>select.onchange=()=>{const a=state.articles.find(a=>a.id===select.value);if(a){const row=select.closest('[data-purchase-line]');row.querySelector('[data-key=unit]').value=a.unit;row.querySelector('[data-key=sku]').value=a.sku;}capturePurchase();});
  const refresh=()=>{capturePurchase();pCalculate();};form.oninput=refresh;pCalculate();
  form.querySelector('[name=supplierId]').onchange=()=>{capturePurchase();const order=pData().orders.find(o=>o.id===editor.record.orderId);if(order&&order.supplierId!==editor.record.supplierId)editor.record.orderId='';renderPurchaseEditor();};
  document.querySelector('#purchase-add-line').onclick=()=>{capturePurchase();editor.record.lines.push(pBlankLine());renderPurchaseEditor();};
  document.querySelectorAll('[data-purchase-remove]').forEach(b=>b.onclick=()=>{capturePurchase();editor.record.lines.splice(+b.dataset.purchaseRemove,1);renderPurchaseEditor();});
  document.querySelector('#purchase-article').onchange=e=>{const a=state.articles.find(a=>a.id===e.target.value);if(!a)return;capturePurchase();const line={...pBlankLine(),articleId:a.id,description:a.name,sku:a.sku,unit:a.unit,vat:a.vat};if(editor.record.lines.length===1&&!editor.record.lines[0].description)editor.record.lines=[line];else editor.record.lines.push(line);renderPurchaseEditor();};
 }
 if(mode==='payment'){let manual=false;form.querySelector('[name=postingDate]').onchange=()=>{manual=true;};form.querySelector('[name=date]').onchange=e=>{if(!manual)form.querySelector('[name=postingDate]').value=e.target.value;};}
 form.onsubmit=async event=>{
  event.preventDefault();capturePurchase();const body=editor.record,button=form.querySelector('[type=submit]');button.disabled=true;
  try{
   const route={supplier:'suppliers',order:'orders',invoice:'invoices',receive:'receipts',cancelOrder:'orders/cancel',closeOrder:'orders/close',reverseReceipt:'receipts/reverse',cancelInvoice:'invoices/cancel',post:'invoices/post',payment:'payments',reversePayment:'payments/reverse'}[mode];
   const result=await post('purchases/'+route,body);editor=null;await load();render();toast(t('saved'));
   if(mode==='order')pOrderView(result.id);else if(['invoice','post','cancelInvoice'].includes(mode))pInvoiceView(mode==='invoice'?result.id:body.id);else if(mode==='payment')pInvoiceView(result.invoiceId);else if(mode==='receive'||mode==='closeOrder'||mode==='cancelOrder')pOrderView(body.id);else if(mode==='reversePayment')pInvoiceView(body.invoiceId);
  }catch(e){button.disabled=false;const error=document.querySelector('#purchase-error');if(error)error.textContent=pError(e);else toast(pError(e));}
 };
